"""Fake bank documents, generated by code (ADR-0005).

Every reader gets documents laid out like its bank's own, with made-up names, numbers and amounts: the tests, the
demo data folder (demo.py) and `iplikci dev parser test` read them, and real documents never enter the repository.
files.py writes the file formats (PDF, XLS, XLSX); a module per bank lays out that bank's documents and offers
them as specimens, each with what its reader must make of it.
"""

import hashlib
from collections.abc import Iterable
from dataclasses import dataclass
from datetime import date
from decimal import Decimal

from ..domain.models import SourceRef
from ..parsers import Skipped, Unreadable, parse_document
from ..parsers.contract import Document

HOLDER = "ÖRNEK KULLANICI"


@dataclass(frozen=True)
class Specimen:
    """A fake document, and what reading it must give."""

    name: str  # its file name
    data: bytes
    reader: str  # the id of the one reader that must take it
    account: str  # the account its first statement, or else its first row, is on; "" for a bill or a receipt
    rows: int  # its rows, statements' and receipts' together, and its bills and receipts


def specimens() -> list[Specimen]:
    """Every reader's fake documents, bank by bank."""
    from . import garanti, invoices, isbank, qnb, teb, vakifbank  # imported here: they import this module

    return [s for bank in (garanti, isbank, teb, qnb, vakifbank, invoices) for s in bank.specimens()]


def check(specimen: Specimen) -> list[str]:
    """What goes wrong when specimen is read, in Turkish; nothing when its reader takes it onto its account with
    its rows, every row knows its place and every statement verifies."""
    doc = Document(specimen.name, "sahte belge", specimen.data, hashlib.sha256(specimen.data).hexdigest())
    try:
        result = parse_document(doc)
    except (Skipped, Unreadable) as exc:
        return [f"okunmadı: {exc}"]
    rows = [t for s in result.statements for t in s.transactions] + result.transactions
    account = result.statements[0].account if result.statements else rows[0].account if rows else ""
    places = [t.ref for t in rows] + [i.ref for i in result.invoices]
    problems: list[str] = []
    if result.parser != specimen.reader:
        problems.append(f"{result.parser} okudu, {specimen.reader} okumalıydı")
    if account != specimen.account:
        problems.append(f"hesap {account}, beklenen {specimen.account}")
    if len(places) != specimen.rows:
        problems.append(f"{len(places)} satır, beklenen {specimen.rows}")
    problems += [
        f"{s.account} ekstresi doğrulanmadı (fark {s.difference})" for s in result.statements if not s.verified
    ]
    if missing := sum(ref is None or ref == SourceRef() for ref in places):
        problems.append(f"kaynak konumu olmayan satır: {missing}")
    return problems


@dataclass(frozen=True)
class Move:
    """A row of an account list: money in is positive, as the banks print it."""

    day: date
    text: str
    amount: Decimal


@dataclass(frozen=True)
class CardRow:
    """A row of a card statement. A row without a day is undated, like the period's interest; a row without an
    amount is a section heading."""

    day: date | None
    text: str
    amount: Decimal | None = None
    extra: str = ""  # the installment or the foreign amount, in a column of its own


@dataclass(frozen=True)
class CardTerms:
    """What a card statement prints for paying it. A term left None is not printed, and neither is one the bank's
    layout has no place for."""

    due: date | None = None  # this statement's due date
    minimum: Decimal | None = None  # the minimum payment
    limit: Decimal | None = None  # the card's limit


def charged(rows: Iterable[CardRow]) -> Decimal:
    """What rows add to a card's debt."""
    return sum((r.amount for r in rows if r.amount is not None), Decimal(0))


def with_balances(moves: Iterable[Move], opening: Decimal = Decimal(0)) -> list[tuple[Move, Decimal]]:
    """moves, in the order given, each with the balance after it."""
    out: list[tuple[Move, Decimal]] = []
    balance = opening
    for m in moves:
        balance += m.amount
        out.append((m, balance))
    return out
